
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_pbetrans_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_pbetrans", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.305202447672209e+00, -4.223598396194037e+00, -4.109375960615812e+00, -3.951412371328595e+00, -3.736725080408525e+00, -3.452184455681559e+00, -3.088498155741147e+00, -2.647326097948938e+00, -2.150201709937116e+00, -1.636939991744058e+00, -1.117265170895338e+00, -7.117168898902683e-01, -6.022054634716096e-01, -5.021807632910121e-01, -3.740820114749079e-01, -2.521471665673325e-01, -1.390197619742101e-01, -4.977649465625670e-02, -1.087165152430820e-02, -1.222943541456649e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


